using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying || EditorSceneManager.GetActiveScene().isDirty)
                throw new Exception("Clean Edit required");
            var before = EditorSceneManager.GetActiveScene().path;
            AssetDatabase.Refresh();
            var scene = EditorSceneManager.OpenScene("Assets/Scenes/JourneyPresentation_v48_r103.unity");
            File.WriteAllText("Test/KetQua/investigation_r103/editor-open.txt", "Previous=" + before + "\nCurrent=" + scene.path + "\nUnity=" + Application.unityVersion + "\nDirty=" + scene.isDirty);
            r.Log("Opened derived r103 without writing r102");
        }
    }
}

